import {api,isDemo} from './api.js';
import config from './config.js';
import {safePhotoUrl} from './security.js';
import {categories,zones,labels,euro,rentalDays,today,distance,available,validateRental,nextActions,filterBookings,escapeHtml as esc} from './domain.js';
import {icon,art} from './art.js';
import {createPushClient} from './notifications.js';
import {preparePhoto,validatePhotoBatch,formatBytes} from './photos.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const categoryIcons=['grid','camera','lens','light','audio','tripod','box'];
const state={listings:[],bookings:[],favorites:readFavorites(),query:'',zone:'',category:'Tutto',sort:'recommended',max:'',start:'',end:'',onlyFavorites:false,free:false,route:'search',currentChat:null,bookingRole:'all',bookingGroup:'all',photoDraft:null,counts:{messages:0,requests:0,byBooking:{}}};
const push=createPushClient(api,{demo:isDemo});
function readFavorites(){try{const value=JSON.parse(localStorage.getItem('sic-favorites')||'[]');return Array.isArray(value)?value.filter(x=>typeof x==='string'):[];}catch{return [];}}
const photo=(l)=>l.images?.[0]?`<img class="product-photo" src="${safeImage(l.images[0])}" alt="${esc(l.title)}" loading="lazy">`:art(l.art||({Camere:'camera',Obiettivi:'lens',Luci:'light',Audio:'audio',Supporti:'tripod',Accessori:'reflector'}[l.category]));
function safeImage(src){return esc(safePhotoUrl(src,{origin:location.origin,backend:config.url,demo:isDemo}));}
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short'});
const period=b=>`${dateLabel(b.start_date)} → ${dateLabel(b.end_date)}`;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
function error(e){toast(e.message||'Qualcosa non ha funzionato. Riprova.');}
async function reload(){state.listings=await api.listings();state.bookings=api.user()?await api.bookings():[];await refreshCounts();}
async function refreshCounts(){state.counts=api.user()?await api.notificationCounts():{messages:0,requests:0,byBooking:{}};renderBadges();await push.updateBadge(state.counts.messages+state.counts.requests);}
function counter(kind){return `<span class="unread-badge" data-count-kind="${kind}" hidden></span>`;}
function renderBadges(){for(const el of document.querySelectorAll('[data-count-kind]')){const n=Number(state.counts[el.dataset.countKind])||0;el.hidden=!n;el.textContent=n>99?'99+':String(n);el.setAttribute('aria-label',`${n} ${el.dataset.countKind==='messages'?'messaggi':'richieste'} non letti`);}for(const el of document.querySelectorAll('[data-thread-count]')){const n=Number(state.counts.byBooking?.[el.dataset.threadCount])||0;el.hidden=!n;el.textContent=n>99?'99+':String(n);}}
function header(){return `<div class="announcement">${isDemo?'<span class="demo-dot"></span> Anteprima interattiva · Annunci e scambi dimostrativi':'Versione pilota · Roma · Attrezzatura condivisa'}${isDemo?'<button data-action="about-demo">Come funziona la demo '+icon('arrow')+'</button>':''}</div><header><a href="#search" class="brand"><img src="/icon.svg" width="37" height="37" alt=""><span>set in comune<span class="brand-dot">.</span></span></a><nav aria-label="Navigazione principale">${[['search','search','Cerca'],['messages','chat','Messaggi'],['bookings','calendar','Prenotazioni']].map(([route,i,label])=>`<a href="#${route}" class="${state.route===route?'active':''}">${icon(i)}<span>${label}</span>${route==='messages'?counter('messages'):route==='bookings'?counter('requests'):''}</a>`).join('')}</nav><div class="header-actions"><button class="btn small primary" data-action="publish">${icon('plus')}<span>Metti a noleggio</span></button><a class="avatar" href="#profile" aria-label="Profilo">${icon('user')}</a></div></header>`;}
function footer(){return `<footer><a class="brand" href="#search">set in comune<span class="brand-dot">.</span></a><p>Più attrezzatura in giro. Più storie sullo schermo.</p><button data-action="how">Come funziona</button><button data-action="privacy">Privacy e condizioni</button><span>Fatto per chi fa cinema · Roma</span></footer><nav class="mobile-nav" aria-label="Navigazione mobile">${[['search','search','Cerca'],['messages','chat','Messaggi'],['bookings','calendar','Noleggi'],['profile','user','Profilo']].map(([r,i,t])=>`<a href="#${r}" class="${state.route===r?'active':''}">${icon(i)}${t}${r==='messages'?counter('messages'):r==='bookings'?counter('requests'):''}</a>`).join('')}</nav>`;}
function shell(html){app.innerHTML=header()+`<main id="main">${html}</main>`+footer();renderBadges();}
function searchPage(){shell(`<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="live-dot"></span> LA TUA COMMUNITY, IL TUO PROSSIMO SET</div><h1>Le belle storie<br>iniziano <em>in comune.</em></h1><p>Trova l’attrezzatura giusta, vicino a te.<br>Noleggia da altri filmmaker e fai spazio alle tue idee.</p><div class="hero-note">${icon('pin')} Si parte da Roma <span>·</span> Da filmmaker a filmmaker</div></div><div class="hero-visual"><div class="film-frame"><div class="frame-top"><span>REC <b>●</b></span><span>ROMA / TAKE 01</span></div>${art('camera')}<div class="frame-bottom"><span>LA TUA PROSSIMA STORIA</span>${icon('plus')}</div></div><div class="floating-tag">${icon('check')} Meno spese. Più cinema.</div><span class="star-shape">✳</span></div></section><section class="search-section" aria-label="Cerca attrezzatura"><form id="search-form" class="searchbar"><label class="search-input">${icon('search')}<span><span>COSA TI SERVE?</span><input name="query" aria-label="Cerca attrezzatura" placeholder="Una camera, una luce, un’idea…" value="${esc(state.query)}"></span></label><label>${icon('pin')}<span><span>DOVE?</span><select name="zone" aria-label="Quartiere">${zoneOptions(state.zone,true)}</select></span></label><label>${icon('calendar')}<span><span>RITIRO</span><input name="start" type="date" aria-label="Data di ritiro" min="${today()}" value="${state.start}"></span></label><label class="end-date"><span><span>RESTITUZIONE</span><input name="end" type="date" aria-label="Data di restituzione" min="${state.start||today()}" value="${state.end}"></span></label><button class="btn primary" type="submit">Cerca ${icon('arrow')}</button></form></section><section class="catalog"><div class="categories" aria-label="Categoria">${categories.map((c,i)=>`<button data-action="category" data-value="${c}" class="category ${state.category===c?'selected':''}">${icon(categoryIcons[i])}${c}</button>`).join('')}<button class="filter-button" data-action="filters">${icon('sliders')} Filtri${state.max||state.free?' •':''}</button></div><div class="catalog-heading"><div><div class="eyebrow">L’ATTREZZATURA È GIÀ QUI</div><h2>${state.onlyFavorites?'I tuoi preferiti':'Il prossimo set, a due passi.'}</h2><p id="results-count"></p></div><div class="catalog-controls"><button class="icon-button ${state.onlyFavorites?'chosen':''}" data-action="favorites" aria-label="Mostra solo preferiti" aria-pressed="${state.onlyFavorites}">${icon('heart')}</button><label class="sort-label">Ordina per <select id="sort" aria-label="Ordina annunci"><option value="recommended" ${state.sort==='recommended'?'selected':''}>In evidenza</option><option value="price" ${state.sort==='price'?'selected':''}>Prezzo crescente</option><option value="distance" ${state.sort==='distance'?'selected':''}>Distanza dal quartiere</option></select></label></div></div><div id="cards" class="cards"></div><div class="trust-strip"><div>${icon('chat')}<span><b>Parlatevi, prima di tutto</b>Concorda i dettagli direttamente in chat.</span></div><div>${icon('shield')}<span><b>Tutto chiaro, dall’inizio</b>Prezzo, cauzione e condizioni ben distinti.</span></div><div>${icon('camera')}<span><b>Da un set all’altro</b>Controlla e fotografa al ritiro e al rientro.</span></div></div></section><section class="community"><div><div class="eyebrow">QUELLA LUCE NON DEVE PRENDERE POLVERE</div><h2>Tra un tuo progetto e l’altro,<br>fai nascere quello di qualcuno.</h2><p>Metti in circolo l’attrezzatura che non stai usando.</p></div><button class="btn primary" data-action="publish">Pubblica il tuo primo annuncio ${icon('arrow')}</button></section>`);renderCards();}
function zoneOptions(value,all=false){return (all?'<option value="">Tutta Roma</option>':'')+Object.keys(zones).map(z=>`<option ${z===value?'selected':''}>${z}</option>`).join('');}
function filtered(){let list=state.listings.filter(l=>(state.category==='Tutto'||l.category===state.category)&&(!state.query||(l.title+' '+l.description).toLowerCase().includes(state.query.toLowerCase()))&&(!state.max||l.price<=Number(state.max))&&(!state.free||l.price===0)&&(!state.onlyFavorites||state.favorites.includes(l.id))&&available(l,state.start,state.end));if(state.zone)list=list.filter(l=>distance(zones[state.zone],zones[l.zone]||zones.Prati)<=10);if(state.sort==='price')list.sort((a,b)=>a.price-b.price);if(state.sort==='distance'&&state.zone)list.sort((a,b)=>distance(zones[state.zone],zones[a.zone])-distance(zones[state.zone],zones[b.zone]));return list;}
function renderCards(){const list=filtered();document.querySelector('#results-count').textContent=`${list.length} ${list.length===1?'attrezzatura':'attrezzature'} ${state.zone?'entro circa 10 km da '+state.zone:'da scoprire a Roma'}${state.start?' · '+dateLabel(state.start)+' – '+dateLabel(state.end):''}${isDemo?' · Esempi dimostrativi':''}`;document.querySelector('#cards').innerHTML=list.length?list.map(l=>`<article class="card"><div class="card-image ${esc(l.color||'sage')}"><button class="card-open" data-action="detail" data-id="${l.id}" aria-label="Apri ${esc(l.title)}">${photo(l)}</button><span class="card-badge">${l.price===0?'In prestito gratuito':esc(l.category)}</span><button class="favorite ${state.favorites.includes(l.id)?'chosen':''}" data-action="favorite" data-id="${l.id}" aria-label="${state.favorites.includes(l.id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${esc(l.title)}" aria-pressed="${state.favorites.includes(l.id)}">${icon('heart')}</button></div><div class="card-info"><div class="location">${icon('pin')}${esc(l.zone)}${state.zone?' · ~'+distance(zones[state.zone],zones[l.zone]).toFixed(1)+' km':''}</div><h3><button data-action="detail" data-id="${l.id}">${esc(l.title)}</button></h3><div class="owner"><span class="mini-avatar">${esc((l.owner_name||'F')[0])}</span>${esc(l.owner_name||'Filmmaker')}${isDemo?'<span class="demo-label">DEMO</span>':''}</div><div class="card-bottom"><div><b>${l.price===0?'Gratis':euro(l.price)}</b>${l.price===0?'':'<span> / giorno</span>'}</div><button class="round-arrow" data-action="detail" data-id="${l.id}" aria-label="Dettagli ${esc(l.title)}">${icon('arrow')}</button></div></div></article>`).join(''):empty('Nessun annuncio trovato','Prova un’altra categoria o modifica i filtri.','reset-filters','Azzera i filtri');}
function empty(title,body,action,label){return `<div class="empty">${icon('camera')}<h2>${title}</h2><p>${body}</p>${action?`<button class="btn primary" data-action="${action}">${label}</button>`:''}</div>`;}
let lastFocus;
function open(html){discardPhotoDraft();lastFocus=document.activeElement;modal.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Chiudi">${icon('close')}</button>${html}`;if(!modal.open)modal.showModal();}
function close(force=false){if(!force&&modal.querySelector('form[data-submitting="true"]'))return;discardPhotoDraft();modal.close();lastFocus?.focus();}
modal.addEventListener('close',discardPhotoDraft);
modal.addEventListener('cancel',e=>{if(modal.querySelector('form[data-submitting="true"]'))e.preventDefault();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function discardPhotoDraft(){if(state.photoDraft){for(const p of state.photoDraft.photos)if(p.file)URL.revokeObjectURL(p.url);state.photoDraft=null;}}
function startPhotoDraft(formId,images=[],max=4){state.photoDraft={formId,max,photos:images.map(url=>({url})),busy:false};renderPhotoDraft();}
function photoPicker(avatar=false){return `<label>${avatar?'Foto profilo':'Foto (fino a 4)'}<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" ${avatar?'':'multiple'}></label><p class="fineprint">JPG, PNG o WebP fino a 15 MB. Le foto vengono ridotte prima del caricamento.${avatar?' Scegli una foto in cui ti si riconosca.':' La prima sarà la copertina.'}</p><div id="photo-preview" class="photo-preview" aria-label="Foto selezionate"></div><p id="photo-progress" class="fineprint" role="status"></p>`;}
function renderPhotoDraft(){const draft=state.photoDraft,el=document.querySelector('#photo-preview');if(!draft||!el)return;el.innerHTML=draft.photos.map((p,i)=>`<div class="photo-tile"><img src="${safeImage(p.url)}" alt="Foto ${i+1}${i===0?', copertina':''}"><span>${i===0?'Copertina':i+1}${p.file?' · '+formatBytes(p.file.size):''}</span><button type="button" class="remove-photo" data-action="remove-photo" data-value="${i}" aria-label="Rimuovi foto ${i+1}">×</button></div>`).join('');const status=document.querySelector('#photo-progress');if(status)status.textContent=draft.busy?'Preparo le foto…':draft.photos.length?`${draft.photos.length}/${draft.max} foto${draft.photos.some(p=>p.file)?' · Nuove foto ottimizzate':''}`:'Nessuna foto selezionata.';}
async function addPhotos(input){const formError=input.closest('form')?.querySelector('.form-error');if(formError)formError.textContent='';const draft=state.photoDraft;if(!draft||draft.busy)return;const files=[...input.files];input.value='';validatePhotoBatch([...draft.photos.map(p=>p.file).filter(Boolean),...files]);if(draft.max===1&&files.length===1){for(const p of draft.photos)if(p.file)URL.revokeObjectURL(p.url);draft.photos=[];}if(draft.photos.length+files.length>draft.max)throw new Error('Hai raggiunto il numero massimo di foto. Rimuovine una per sostituirla.');draft.busy=true;const form=input.closest('form'),submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;renderPhotoDraft();const added=[];try{for(const file of files){const prepared=await preparePhoto(file);if(state.photoDraft!==draft)return;added.push({file:prepared,url:URL.createObjectURL(prepared)});}draft.photos.push(...added);added.length=0;}finally{for(const p of added)URL.revokeObjectURL(p.url);draft.busy=false;if(submit)submit.disabled=false;if(state.photoDraft===draft)renderPhotoDraft();}}
async function saveWithPhotos(draft,privateBooking,saveRecord){if(draft?.busy)throw new Error('Attendi che le foto siano pronte.');const refs=[],uploaded=[];try{for(const p of draft?.photos||[]){if(p.file){const ref=await api.upload(p.file,privateBooking,draft.formId==='avatar-form');refs.push(ref);uploaded.push(ref);}else refs.push(p.url);}return await saveRecord(refs);}catch(e){try{await api.removeUploads(uploaded,privateBooking,draft?.formId==='avatar-form');}catch{throw new Error(e.message+' Alcune foto caricate non sono state rimosse: riprova più tardi o contatta il gestore.');}throw e;}}
function guard(){if(api.user())return true;loginDialog();return false;}
function loginDialog(signup=false){open(`<div class="modal-heading"><div class="eyebrow">BENVENUTO NELLA COMMUNITY</div><h2>${signup?'Il tuo prossimo set inizia qui.':'Bentornato, filmmaker.'}</h2><p>Un account per cercare e condividere attrezzatura.</p></div><form id="auth-form" class="stack" data-signup="${signup}">${signup?'<label>Come ti chiami?<input name="display_name" required minlength="2" maxlength="60" autocomplete="name"></label>':''}<label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="${signup?'new-password':'current-password'}"></label><button class="btn primary">${signup?'Crea account':'Accedi'}</button><p class="form-error" role="alert"></p></form><button class="text-button" data-action="${signup?'login':'signup'}">${signup?'Hai già un account? Accedi':'Prima volta? Crea un account'}</button>${signup?'':'<button class="text-button" data-action="reset-password">Password dimenticata</button>'}`);}
function detail(id){const l=state.listings.find(x=>x.id===id);if(!l)return;open(`${listingGallery(l)}<div class="eyebrow">${esc(l.category)} · ${esc(l.zone)}</div><h2>${esc(l.title)}</h2><button class="person-link" data-action="public-profile" data-id="${l.owner_id}">${icon('user')} Condivisa da ${esc(l.owner_name||'un filmmaker')} ${icon('arrow')}</button>${isDemo?'<p class="fineprint">Annuncio e profilo dimostrativi</p>':''}<p>${esc(l.description)}</p><div class="detail-facts"><div><span>Noleggio</span><b>${euro(l.price)} / giorno</b></div><div><span>Cauzione separata</span><b>${euro(l.deposit)}</b></div></div><details open><summary>Accessori inclusi</summary><p>${esc(l.accessories)}</p></details><details><summary>Condizioni e assicurazione</summary><p>${esc(l.conditions)}</p><p>${esc(l.insurance)}</p><p>La piattaforma non fornisce una copertura assicurativa.</p></details><div class="notice">${icon('pin')} L’indirizzo preciso si concorda in chat dopo l’accettazione. La distanza è stimata tra i quartieri.</div>${l.owner_id===api.user()?.id?'<p>Questa è la tua attrezzatura. Gestiscila dal Profilo.</p>':`<form id="booking-form" class="stack" data-id="${l.id}"><div class="form-grid"><label>Ritiro<input type="date" name="start_date" min="${today()}" value="${state.start}" required></label><label>Restituzione<input type="date" name="end_date" min="${state.start||today()}" value="${state.end}" required></label></div><label>Racconta il tuo progetto<textarea name="note" maxlength="2000" placeholder="Quando vorresti ritirarla? Per che tipo di riprese?" rows="3"></textarea></label><div id="quote" class="quote">Scegli le date per calcolare il totale.</div><p class="fineprint">Pagamento e cauzione direttamente tra voi. Nessun addebito in app. Le date includono sia il giorno di ritiro sia quello di restituzione.</p><button class="btn primary">${isDemo?'Prova la richiesta':'Invia richiesta'} ${icon('arrow')}</button><p class="form-error" role="alert"></p></form>`}`);updateQuote();}
function listingGallery(l){return `<div id="detail-main" class="detail-art ${esc(l.color||'sage')}">${photo(l)}</div>${l.images?.length>1?`<div class="gallery-thumbs" aria-label="Galleria foto">${l.images.map((url,i)=>`<button data-action="gallery-photo" data-id="${l.id}" data-value="${i}" aria-label="Mostra foto ${i+1}" aria-pressed="${i===0}"><img src="${safeImage(url)}" alt="Foto ${i+1}"></button>`).join('')}</div>`:''}`;}
function updateQuote(){const f=document.querySelector('#booking-form');if(!f)return;const l=state.listings.find(l=>l.id===f.dataset.id);const start=f.elements.start_date.value,end=f.elements.end_date.value;f.elements.end_date.min=start||today();const days=rentalDays(start,end);document.querySelector('#quote').textContent=days?`${days} ${days===1?'giorno':'giorni'} · Noleggio ${euro(days*l.price)} + cauzione ${euro(l.deposit)} (separata)`:'Scegli un periodo valido.';}
function filtersDialog(){open(`<h2>Un set su misura.</h2><form id="filters-form" class="stack"><label>Prezzo massimo al giorno (€)<input type="number" name="max" min="0" max="10000" step="1" value="${state.max}" placeholder="Nessun limite"></label><label class="check-label"><input type="checkbox" name="free" ${state.free?'checked':''}> Solo prestiti gratuiti</label><button class="btn primary">Applica filtri</button><button type="button" class="btn secondary" data-action="reset-filters">Azzera tutti i filtri</button></form>`);}
async function bookingsPage(){if(!api.user()){shell(empty('I tuoi prossimi set, tutti qui.','Accedi per vedere richieste e prenotazioni.','login','Accedi'));return;}state.bookings=await api.bookings();const list=filterBookings(state.bookings,api.user().id,state.bookingRole,state.bookingGroup);shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">DAL PRIMO CIAO ALL’ULTIMO CIAK</div><h1>Le tue prenotazioni<span>.</span></h1><p>Richieste, ritiri e restituzioni. Tutto in un posto.</p></div><button class="btn secondary" data-action="refresh">${icon('calendar')} Aggiorna</button></div><div class="booking-filters"><div class="filter-tabs" aria-label="Tipo di prenotazione">${[['all','Tutte'],['renter','Cerco attrezzatura'],['owner','La mia attrezzatura']].map(([v,t])=>`<button class="${state.bookingRole===v?'selected':''}" data-action="booking-role" data-value="${v}" aria-pressed="${state.bookingRole===v}">${t}</button>`).join('')}</div><label>Stato <select id="booking-group" aria-label="Stato prenotazioni">${[['all','Tutti gli stati'],['pending','In attesa'],['active','Da ritirare / in corso'],['history','Storico']].map(([v,t])=>`<option value="${v}" ${state.bookingGroup===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="fineprint booking-count">${list.length} ${list.length===1?'prenotazione':'prenotazioni'}</p>${list.length?`<div class="booking-list">${list.map(b=>bookingCard(b)).join('')}</div>`:empty(state.bookings.length?'Nessuna prenotazione con questi filtri.':'Il prossimo set ti aspetta.',state.bookings.length?'Cambia tipo o stato per ritrovare le tue richieste.':'Cerca un’attrezzatura e invia la tua prima richiesta.',state.bookings.length?'reset-booking-filters':'go-search',state.bookings.length?'Mostra tutte':'Esplora attrezzatura')}</section>`);await Promise.all(list.filter(b=>b.owner_id===api.user().id).map(b=>api.readNotifications(b.id,'request',b.created_at)));await refreshCounts();}
function bookingCard(b){const owner=b.owner_id===api.user()?.id;const actions=nextActions(b.status,owner);const actionNames={accepted:'Accetta richiesta',declined:'Rifiuta',cancelled:'Annulla',collected:'Conferma consegna',returned:'Registra restituzione',completed:'Chiudi noleggio'};return `<article class="booking-card"><div class="booking-top"><span class="status ${b.status}">${labels[b.status]}</span><span class="fineprint">${owner?'La tua attrezzatura':'La tua richiesta'}${isDemo?' · Demo':''}</span></div><h2>${esc(b.title)}</h2><button class="person-link" data-action="public-profile" data-id="${owner?b.renter_id:b.owner_id}">${icon('user')} ${owner?'Richiesta di '+esc(b.renter_name||'un filmmaker'):'Vedi il profilo del proprietario'} ${icon('arrow')}</button><div class="booking-meta"><span>${icon('calendar')} ${period(b)}</span><span>Noleggio <b>${euro(b.total)}</b></span><span>Cauzione <b>${euro(b.deposit)}</b></span></div><p>${esc(b.note||'Nessuna nota aggiuntiva.')}</p><details><summary>Accordo e condizioni salvate</summary><p>Accessori: ${esc(b.accessories)}</p><p>Condizioni: ${esc(b.conditions)}</p><p>Assicurazione dichiarata: ${esc(b.insurance)}</p><p>Pagamento esterno. La chiusura non effettua rimborsi o trasferimenti di denaro.</p></details><div class="booking-actions"><button class="btn secondary small" data-action="chat" data-id="${b.id}">${icon('chat')} Apri chat</button><button class="btn text small" data-action="evidence" data-id="${b.id}">Registro noleggio</button>${actions.map(a=>`<button class="btn ${['declined','cancelled'].includes(a)?'text':'primary'} small" data-action="transition" data-id="${b.id}" data-value="${a}">${actionNames[a]}</button>`).join('')}${isDemo&&!owner&&b.status==='requested'?`<button class="btn demo-button small" data-action="demo-accept" data-id="${b.id}">Simula accettazione</button>`:''}${isDemo&&!owner&&['accepted','returned'].includes(b.status)?`<button class="btn demo-button small" data-action="demo-handoff" data-id="${b.id}">Simula ${b.status==='accepted'?'consegna':'chiusura'}</button>`:''}</div></article>`;}
function transitionDialog(id,status){const b=state.bookings.find(x=>x.id===id);const handoff=['collected','returned','completed'].includes(status);open(`<h2>${({accepted:'Conferma le date',declined:'Rifiuta la richiesta',cancelled:'Annulla la prenotazione',collected:'Pronti per il ciak.',returned:'L’attrezzatura torna a casa.',completed:'Un altro set, concluso.'})[status]}</h2><p>${esc(b.title)} · ${period(b)}</p><form id="transition-form" class="stack" data-id="${id}" data-status="${status}">${handoff?`<label class="check-label"><input type="checkbox" name="checked" required> Ho controllato attrezzatura e accessori con l’altra persona.</label>${photoPicker()}`:''}<label>Note ${handoff?'sullo stato dell’attrezzatura':''}<textarea name="note" rows="3" maxlength="2000" placeholder="${handoff?'Segna eventuali differenze, danni o accessori mancanti.':'Aggiungi una nota, se necessario.'}"></textarea></label>${status==='completed'?'<div class="notice">Concordate separatamente l’eventuale restituzione della cauzione. L’app non sposta denaro.</div>':''}<button type="submit" class="btn primary">Conferma</button><p class="form-error" role="alert"></p></form>`);if(handoff)startPhotoDraft('transition-form');}
async function messagesPage(){if(!api.user()){shell(empty('Ogni set inizia con un messaggio.','Accedi per parlare con altri filmmaker.','login','Accedi'));return;}state.bookings=await api.bookings();if(!state.bookings.length){shell(`<section class="page">${empty('Ancora nessuna conversazione.','Invia una richiesta da un annuncio per aprire una chat.','go-search','Trova attrezzatura')}</section>`);return;}if(!state.currentChat||!state.bookings.some(b=>b.id===state.currentChat))state.currentChat=state.bookings[0].id;const b=state.bookings.find(b=>b.id===state.currentChat);const people=new Map(await Promise.all([...new Set(state.bookings.map(x=>x.owner_id===api.user().id?x.renter_id:x.owner_id))].map(async id=>{try{return [id,await api.publicProfile(id)];}catch{return [id,{display_name:'Profilo non disponibile'}];}})));shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">CONOSCI CHI C’È DALL’ALTRA PARTE</div><h1>Messaggi<span>.</span></h1></div><button class="btn secondary" data-action="refresh">Aggiorna</button></div><div class="messenger"><aside class="threads" aria-label="Conversazioni">${state.bookings.map(x=>`<button data-action="select-chat" data-id="${x.id}" class="thread ${x.id===b.id?'selected':''}">${avatar(people.get(x.owner_id===api.user().id?x.renter_id:x.owner_id)||{})}<span><b>${esc(people.get(x.owner_id===api.user().id?x.renter_id:x.owner_id)?.display_name||'Filmmaker')}</b><small>${esc(x.title)}</small><small>${period(x)} · ${labels[x.status]}</small></span><span class="unread-badge" data-thread-count="${x.id}" hidden></span>${icon('arrow')}</button>`).join('')}</aside><div class="conversation"><div class="conversation-header"><div><b>${esc(b.title)}</b><button class="person-link" data-action="public-profile" data-id="${b.owner_id===api.user().id?b.renter_id:b.owner_id}">Vedi il profilo della persona ${icon('arrow')}</button></div><span class="status ${b.status}">${labels[b.status]}</span></div><p class="conversation-note">${isDemo?'Demo: i messaggi restano su questo dispositivo e non vengono inviati a persone reali.':b.status==='requested'?'Concorda i dettagli del noleggio. Condividi l’indirizzo preciso dopo la conferma.':'Concordate qui indirizzo, orario e modalità di pagamento diretto.'}</p><div id="messages" class="messages" role="log" aria-label="Messaggi della conversazione"></div><form id="message-form" data-id="${b.id}" class="message-form"><label class="sr-only" for="message-input">Il tuo messaggio</label><input id="message-input" name="body" required maxlength="2000" placeholder="Scrivi un messaggio…" autocomplete="off"><button class="btn primary" aria-label="Invia messaggio">${icon('arrow')}</button></form></div></div></section>`);await loadMessages();}
async function loadMessages(){const id=state.currentChat;const messages=await api.messages(id);if(!document.querySelector('#messages')||state.currentChat!==id)return;const box=document.querySelector('#messages');const signature=JSON.stringify(messages);if(box.dataset.signature===signature)return;const atBottom=!box.dataset.signature||box.scrollHeight-box.scrollTop-box.clientHeight<80;box.dataset.signature=signature;box.innerHTML=messages.length?messages.map(m=>`<div class="bubble ${m.sender_id===api.user().id?'mine':''}"><p>${esc(m.body)}</p><time>${new Date(m.created_at).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>`).join(''):'<p class="empty-chat">Presentati e racconta cosa hai in mente per il tuo set.</p>';if(atBottom)box.scrollTop=box.scrollHeight;if(!document.hidden&&messages.length){await api.readNotifications(id,'message',messages.at(-1).created_at);await refreshCounts();}}
function avatar(p,large=false){return `<span class="person-avatar ${large?'large':''}">${p.avatar_url?`<img src="${safeImage(p.avatar_url)}" alt="Foto profilo di ${esc(p.display_name)}">`:esc((p.display_name||'F').trim().slice(0,1).toUpperCase())}</span>`;}
async function publicProfileDialog(id){const [p,list]=await Promise.all([api.publicProfile(id),api.publicListings(id)]);open(`<div class="public-profile-header">${avatar(p,true)}<div><div class="eyebrow">${isDemo?'PROFILO DIMOSTRATIVO':'NELLA COMMUNITY'}</div><h2>${esc(p.display_name)}</h2><p>${icon('pin')} ${esc(p.zone||'Roma')}</p></div></div><div class="profile-signals">${!isDemo&&p.email_verified?'<span>Email confermata</span>':''}<span>${p.avatar_url?'Foto aggiunta':'Foto non aggiunta'}</span><span>${p.bio?.trim()?'Bio aggiunta':'Bio non aggiunta'}</span></div><h3>Qualcosa su di me</h3><p class="public-bio">${esc(p.bio?.trim()||'Questa persona non ha ancora aggiunto una bio.')}</p><p class="fineprint">Foto e bio sono facoltative e dichiarate dall’utente. La conferma email non è una verifica del documento d’identità.</p><h3 class="public-listings-title">Attrezzatura condivisa · ${list.length}</h3>${list.length?`<div class="public-listings">${list.map(l=>`<button class="public-listing" data-action="profile-listing" data-id="${l.id}"><span>${esc(l.title)}<small>${esc(l.zone)}</small></span><b>${l.price===0?'Gratis':euro(l.price)+'/giorno'}</b>${icon('arrow')}</button>`).join('')}</div>`:'<p>Nessun annuncio attivo. Il profilo serve anche a chi cerca attrezzatura.</p>'}`);}
async function avatarDialog(){const p=await api.profile();open(`<h2>Fatti riconoscere.</h2><p>La foto è facoltativa e visibile a chi visita il tuo profilo.</p><form id="avatar-form" class="stack">${photoPicker(true)}<button type="submit" class="btn primary">Salva foto profilo</button><p class="form-error" role="alert"></p></form>`);startPhotoDraft('avatar-form',p.avatar_url?[p.avatar_url]:[],1);}
async function notificationPanel(){let status;try{status=await push.status();}catch{status=push.capabilities();}const iosHelp=status.ios&&!status.installed;return `<section class="panel notifications-panel"><div class="eyebrow">RESTIAMO IN CONTATTO</div><h2>Notifiche</h2><p>Ricevi un avviso quando qualcuno ti scrive o chiede la tua attrezzatura, anche se non stai guardando l’app.</p><p class="notification-status" role="status">${isDemo?'Nella demo vedi i contatori nell’app. Le push tra persone reali richiedono il collegamento al pilota.':iosHelp?'Aggiungi prima l’app alla schermata Home dell’iPhone.':!status.supported?'Questo browser non supporta le notifiche push.':status.permission==='denied'?'Notifiche bloccate nelle impostazioni del browser.':status.enabled?'Attive su questo dispositivo.':'Non ancora attive su questo dispositivo.'}</p>${iosHelp?'<ol class="install-steps"><li>Apri il sito in Safari.</li><li>Tocca Condividi → Aggiungi alla schermata Home.</li><li>Apri l’app dall’icona e torna qui per attivarle.</li></ol>':''}<form id="notification-form" class="stack"><label class="check-label"><input type="checkbox" name="messages" ${status.messages!==false?'checked':''}> Nuovi messaggi</label><label class="check-label"><input type="checkbox" name="requests" ${status.requests!==false?'checked':''}> Nuove richieste di noleggio</label><button type="submit" class="btn primary" ${isDemo||iosHelp||!status.supported?'disabled':''}>${status.enabled?'Salva preferenze':'Attiva notifiche'}</button><p class="form-error" role="alert"></p></form>${status.enabled?'<button class="text-button" data-action="disable-push">Disattiva su questo dispositivo</button>':''}<button class="text-button" data-action="install-app">Come aggiungere l’app alla Home</button><p class="fineprint">Puoi disattivarle quando vuoi. Le email restano riservate a conferma dell’indirizzo e recupero password.</p></section>`;}
function installDialog(){open('<h2>La tua app, sempre a portata.</h2><p>Su iPhone: apri in Safari, tocca Condividi e scegli Aggiungi alla schermata Home. Se compare, attiva Apri come app web. Poi apri dall’icona: da Profilo puoi autorizzare le notifiche.</p><p>Su Android o computer: cerca Installa app o Aggiungi alla schermata Home nel menu del browser.</p><button class="btn primary" data-action="close">Ho capito</button>');}
async function profilePage(){if(!api.user()){shell(`<section class="page">${empty('Una community. Un solo profilo.','Cerca l’attrezzatura degli altri e metti a noleggio la tua.','login','Accedi o registrati')}</section>`);return;}const [p,mine,notifications]=await Promise.all([api.profile(),api.myListings(),notificationPanel()]);shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">IL TUO ANGOLO DI COMMUNITY</div><h1>Ciao, ${esc(p?.display_name||'filmmaker')}<span>.</span></h1><p>${isDemo?'Stai usando un profilo demo, salvato solo in questo browser.':esc(api.user().email)}</p></div><button class="btn secondary" data-action="${isDemo?'reset-demo':'logout'}">${isDemo?'Ripristina demo':'Esci'}</button></div><div class="profile-grid"><div><div class="profile-identity panel">${avatar(p||{},true)}<h2>${esc(p?.display_name||'Il tuo profilo')}</h2><p class="fineprint">${isDemo?'Profilo dimostrativo':p?.email_verified?'Email confermata':'Email da confermare'}</p><button class="btn secondary small" data-action="edit-avatar">${p?.avatar_url?'Cambia foto':'Aggiungi foto profilo'}</button><button class="text-button" data-action="public-profile" data-id="${api.user().id}">Guarda il tuo profilo pubblico</button></div><form id="profile-form" class="panel stack"><h2>Il tuo profilo</h2><label>Nome visibile<input name="display_name" value="${esc(p?.display_name||'')}" required minlength="2" maxlength="60"></label><label>Il tuo quartiere<select name="zone">${zoneOptions(p?.zone||'Prati')}</select></label><label>Qualcosa su di te (facoltativo)<textarea name="bio" maxlength="600" rows="4">${esc(p?.bio||'')}</textarea></label><button class="btn primary">Salva profilo</button><p class="form-error" role="alert"></p></form>${notifications}</div><div><div class="section-title"><h2>La tua attrezzatura</h2><button class="btn primary small" data-action="publish">${icon('plus')} Aggiungi</button></div>${mine.length?mine.map(l=>`<article class="my-listing"><div class="my-art ${esc(l.color||'sage')}">${photo(l)}</div><div><h3>${esc(l.title)}</h3><p>${euro(l.price)}/giorno · ${esc(l.zone)} · ${l.active?'Pubblicato':'In pausa'}</p><p class="fineprint">${(l.blocked||[]).length} periodi bloccati</p><div class="booking-actions"><button class="btn secondary small" data-action="toggle-listing" data-id="${l.id}" data-value="${!l.active}">${l.active?'Metti in pausa':'Ripubblica'}</button><button class="btn secondary small" data-action="edit-listing" data-id="${l.id}">Modifica</button><button class="btn text small" data-action="availability" data-id="${l.id}">Disponibilità</button></div></div></article>`).join(''):empty('Falla uscire dalla borsa.','Pubblica la tua prima attrezzatura.','publish','Crea annuncio')}</div></div></section>`);}
function publishDialog(listing=null){if(!guard())return;const editing=Boolean(listing),v=k=>esc(listing?.[k]??'');open(`<div class="eyebrow">UN’ATTREZZATURA, NUOVE POSSIBILITÀ</div><h2>${editing?'Il tuo annuncio, aggiornato.':'Cosa metti in comune?'}</h2>${editing?'<p class="fineprint">Le modifiche valgono per le nuove richieste. Prezzi e condizioni delle richieste già inviate restano quelli salvati.</p>':''}<form id="publish-form" class="stack" ${editing?`data-id="${listing.id}"`:''}><label>Titolo dell’annuncio<input name="title" value="${v('title')}" required minlength="5" maxlength="90" placeholder="Es. Sony A7 IV + 2 batterie"></label><div class="form-grid"><label>Categoria<select name="category">${categories.slice(1).map(c=>`<option ${listing?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Quartiere<select name="zone">${zoneOptions(listing?.zone||'Prati')}</select></label></div><label>Descrizione<textarea name="description" required minlength="20" maxlength="2000" rows="3" placeholder="Descrivi attrezzatura, condizioni e utilizzi consigliati.">${v('description')}</textarea></label><div class="form-grid"><label>Prezzo al giorno (€)<input type="number" name="price" value="${v('price')}" min="0" max="10000" step="0.01" required placeholder="0 per un prestito gratuito"></label><label>Cauzione (€)<input type="number" name="deposit" value="${listing?.deposit??0}" min="0" max="100000" step="0.01" required></label></div><label>Accessori inclusi<textarea name="accessories" required maxlength="1500" rows="2" placeholder="Elenca esattamente cosa consegnerai.">${v('accessories')}</textarea></label><label>Condizioni di noleggio<textarea name="conditions" required maxlength="1500" rows="2" placeholder="Orari, precauzioni, cosa deve portare chi ritira…">${v('conditions')}</textarea></label><label>Copertura assicurativa dichiarata<textarea name="insurance" required maxlength="1000" rows="2">${editing?v('insurance'):'Nessuna copertura inclusa.'}</textarea></label><p class="fineprint">Se esiste una polizza, descrivi copertura, esclusioni e requisiti. La piattaforma non vende né garantisce assicurazioni.</p>${photoPicker()}<label class="check-label"><input type="checkbox" required> Confermo di poter mettere a noleggio questa attrezzatura e che le informazioni sono corrette.</label><button type="submit" class="btn primary">${editing?'Salva modifiche':isDemo?'Pubblica nella demo':'Pubblica annuncio'} ${icon('arrow')}</button><p class="form-error" role="alert"></p></form>`);startPhotoDraft('publish-form',listing?.images||[]);}
async function route(){const [path,query='']=location.hash.slice(1).split('?');state.route=path||'search';const linked=new URLSearchParams(query).get('booking');if(linked&&/^[a-f0-9-]{36}$/i.test(linked))state.currentChat=linked;if(!['search','messages','bookings','profile'].includes(state.route))state.route='search';try{if(state.route==='search')searchPage();if(state.route==='bookings')await bookingsPage();if(state.route==='messages')await messagesPage();if(state.route==='profile')await profilePage();}catch(e){shell(empty('Non siamo riusciti a caricare la pagina.',esc(e.message),'refresh','Riprova'));}}
function go(where){if(location.hash==='#'+where)route();else location.hash=where;}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;try{
 if(action==='close')close();
 if(action==='detail')detail(id);
 if(action==='install-app'){if(!await push.install())installDialog();}
 if(action==='disable-push'){await push.disable();await profilePage();toast('Notifiche disattivate su questo dispositivo.');}
 if(action==='public-profile')await publicProfileDialog(id);
 if(action==='edit-avatar')await avatarDialog();
 if(action==='profile-listing'){if(!state.listings.some(l=>l.id===id))await reload();detail(id);}
 if(action==='edit-listing'){const listing=(await api.myListings()).find(l=>l.id===id);if(!listing)throw new Error('Annuncio non trovato.');publishDialog(listing);}
 if(action==='remove-photo'){const draft=state.photoDraft;if(draft&&!draft.busy){const [p]=draft.photos.splice(Number(value),1);if(p?.file)URL.revokeObjectURL(p.url);renderPhotoDraft();}}
 if(action==='gallery-photo'){const l=state.listings.find(l=>l.id===id),url=l?.images?.[Number(value)];if(url){document.querySelector('#detail-main').innerHTML=`<img class="product-photo" src="${safeImage(url)}" alt="${esc(l.title)} · foto ${Number(value)+1}">`;document.querySelectorAll('.gallery-thumbs button').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));}}
 if(action==='booking-role'){state.bookingRole=value;await bookingsPage();}
 if(action==='reset-booking-filters'){state.bookingRole='all';state.bookingGroup='all';await bookingsPage();}
 if(action==='category'){state.category=value;searchPage();}
 if(action==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];localStorage.setItem('sic-favorites',JSON.stringify(state.favorites));renderCards();}
 if(action==='favorites'){state.onlyFavorites=!state.onlyFavorites;searchPage();}
 if(action==='filters')filtersDialog();
 if(action==='reset-filters'){Object.assign(state,{query:'',zone:'',category:'Tutto',max:'',free:false,onlyFavorites:false,start:'',end:''});close();searchPage();}
 if(action==='publish')publishDialog();
 if(action==='login')loginDialog();
 if(action==='signup')loginDialog(true);
 if(action==='logout'){try{await push.disable();}catch{}await api.logout();await reload();route();}
 if(action==='reset-password')open('<h2>Recupera il tuo account</h2><form id="reset-form" class="stack"><label>Email<input name="email" type="email" required></label><button class="btn primary">Invia link di recupero</button><p class="form-error" role="alert"></p></form>');
 if(action==='refresh'){await reload();await route();toast('Aggiornato.');}
 if(action==='go-search')go('search');
 if(action==='transition')transitionDialog(id,value);
 if(action==='chat'){state.currentChat=id;go('messages');}
 if(action==='select-chat'){state.currentChat=id;await messagesPage();}
 if(action==='demo-accept'){await api.demoAccept(id);await refreshCounts();await bookingsPage();toast('Risposta simulata: nessun messaggio inviato a persone reali.');}
 if(action==='demo-handoff'){await api.demoHandoff(id);await bookingsPage();}
 if(action==='toggle-listing'){await api.toggleListing(id,value==='true');await reload();await profilePage();}
 if(action==='availability'){const l=(await api.myListings()).find(l=>l.id===id);open(`<h2>Disponibilità</h2><p>${esc(l.title)}</p><p class="fineprint">Le prenotazioni accettate bloccano automaticamente le date. Qui puoi bloccare i giorni in cui la usi tu.</p>${(l.blocked||[]).map(p=>`<p>${period(p)}</p>`).join('')}<form id="block-form" data-id="${id}" class="stack"><div class="form-grid"><label>Dal<input type="date" name="start" min="${today()}" required></label><label>Al<input type="date" name="end" min="${today()}" required></label></div><button class="btn primary">Blocca periodo</button><p class="form-error" role="alert"></p></form>${l.blocked?.length?`<button class="text-button" data-action="unblock" data-id="${id}">Rimuovi tutti i blocchi manuali</button>`:''}`);}
 if(action==='unblock'){await api.unblock(id);close();await reload();await profilePage();}
 if(action==='evidence'){const entries=await api.evidence(id);const rendered=await Promise.all(entries.map(async x=>`<article class="evidence"><b>${labels[x.stage]||esc(x.stage)}</b><small>${new Date(x.created_at).toLocaleString('it-IT')}</small><p>${esc(x.note||'Nessuna nota.')}</p><div class="evidence-photos">${(await Promise.all((x.photos||[]).map(async p=>`<img src="${safeImage(await api.photoUrl(p))}" alt="Foto di riscontro del noleggio">`))).join('')}</div></article>`));open(`<h2>Registro del noleggio</h2>${rendered.join('')||'<p>Nessuna consegna o restituzione registrata.</p>'}`);}
 if(action==='reset-demo')open('<h2>Ripartire da zero?</h2><p>Verranno cancellati solo annunci, richieste e messaggi della demo salvati su questo browser.</p><button class="btn primary" data-action="confirm-reset">Ripristina demo</button>');
 if(action==='confirm-reset')api.resetDemo();
 if(action==='about-demo')open('<div class="eyebrow">ANTEPRIMA INTERATTIVA</div><h2>Provala come fosse il tuo prossimo set.</h2><p>Questi annunci sono esempi. Puoi cercare, pubblicare un annuncio, inviare una richiesta e simulare la risposta del proprietario dalle Prenotazioni.</p><p>I dati restano in questo browser. Non ci sono utenti reali, notifiche o pagamenti. Il collegamento al database abiliterà account e scambi reali.</p><button class="btn primary" data-action="close">Esplora la demo</button>');
 if(action==='how')open('<div class="eyebrow">DA UN FILMMAKER ALL’ALTRO</div><h2>Quattro passi, un nuovo set.</h2><ol class="steps"><li><b>Trova l’attrezzatura.</b> Cerca per categoria, quartiere e date.</li><li><b>Invia una richiesta.</b> Il proprietario conferma e vi accordate in chat.</li><li><b>Ritira e gira.</b> Pagamento e cauzione sono tra voi. Controllate insieme attrezzatura e accessori.</li><li><b>Restituisci e chiudi.</b> Registrate il rientro con note e foto e concordate la cauzione.</li></ol>');
 if(action==='privacy')open(`<h2>Prima di iniziare</h2><p>${isDemo?'Questa è una demo: i dati inseriti sono salvati localmente nel browser. Non inserire dati sensibili. Puoi cancellarli da Profilo → Ripristina demo.':'Questa versione pilota conserva profilo, annunci, richieste, messaggi e foto nel servizio database configurato dal gestore.'}</p><p>Indirizzi precisi e dettagli del ritiro vanno condivisi solo con la controparte dopo la conferma. Le foto degli annunci sono pubbliche; quelle di consegna sono riservate ai partecipanti.</p><p>Prima dell’apertura pubblica devono essere completati i documenti del gestore: informativa privacy, termini del servizio, tempi di conservazione e contatto per assistenza e richieste sui dati.</p><p>Noleggio, pagamento, cauzione e coperture assicurative sono concordati tra le parti. L’app non effettua pagamenti né rimborsi.</p>`);
}catch(err){error(err);}});
document.addEventListener('change',async e=>{try{if(e.target.name==='photos'){await addPhotos(e.target);}if(e.target.id==='booking-group'){state.bookingGroup=e.target.value;await bookingsPage();}if(e.target.id==='sort'){state.sort=e.target.value;if(state.sort==='distance'&&!state.zone)toast('Seleziona un quartiere per ordinare per distanza.');renderCards();}if(e.target.closest('#booking-form'))updateQuote();if(e.target.name==='start'){const end=document.querySelector('[name=end]');if(end)end.min=e.target.value||today();}}catch(ex){const el=e.target.closest('form')?.querySelector('.form-error');if(el)el.textContent=ex.message;else error(ex);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(f.dataset.submitting==='true')return;f.dataset.submitting='true';const data=new FormData(f);const button=f.querySelector('button[type="submit"],button:not([type])');const err=f.querySelector('.form-error');if(err)err.textContent='';if(button)button.disabled=true;try{
 if(f.id==='search-form'){const start=data.get('start'),end=data.get('end');if(Boolean(start)!==Boolean(end))throw new Error('Seleziona entrambe le date oppure lasciale vuote.');if(start)validateRental(start,end);Object.assign(state,{query:data.get('query').trim(),zone:data.get('zone'),start,end});searchPage();document.querySelector('.catalog').scrollIntoView({behavior:'smooth',block:'start'});}
 if(f.id==='filters-form'){state.max=data.get('max');state.free=data.has('free');close(true);searchPage();}
 if(f.id==='notification-form'){const messages=data.has('messages'),requests=data.has('requests');if(!messages&&!requests)await push.disable();else await push.enable({messages,requests});await profilePage();toast(messages||requests?'Notifiche attivate su questo dispositivo.':'Notifiche disattivate.');}
 if(f.id==='auth-form'){if(f.dataset.signup==='true'){const logged=await api.signup(data.get('email'),data.get('password'),data.get('display_name'));if(!logged){open('<h2>Controlla la tua email.</h2><p>Se la registrazione è disponibile, riceverai un messaggio per confermare l’indirizzo. Poi torna qui e accedi.</p>');return;}}else await api.login(data.get('email'),data.get('password'));close(true);await reload();await route();toast('Benvenuto in community.');}
 if(f.id==='reset-form'){await api.reset(data.get('email'));open('<h2>Controlla la tua email.</h2><p>Se l’indirizzo è registrato, riceverai le istruzioni di recupero.</p>');}
 if(f.id==='password-form'){await api.changePassword(data.get('password'));close(true);toast('Password aggiornata.');}
 if(f.id==='booking-form'){if(!guard())return;const l=state.listings.find(l=>l.id===f.dataset.id);await api.createBooking(l,data.get('start_date'),data.get('end_date'),data.get('note').trim());close(true);go('bookings');toast(isDemo?'Richiesta demo creata. Puoi simulare l’accettazione.':'Richiesta inviata.');}
 if(f.id==='profile-form'){await api.saveProfile({display_name:data.get('display_name').trim(),zone:data.get('zone'),bio:data.get('bio').trim()});await reload();await profilePage();toast('Profilo aggiornato.');}
 if(f.id==='avatar-form'){await saveWithPhotos(state.photoDraft,null,refs=>api.saveProfile({avatar_url:refs[0]||''}));close(true);await profilePage();toast('Foto profilo aggiornata.');}
 if(f.id==='publish-form'){const draft=state.photoDraft;if(!isDemo&&!draft?.photos.length)throw new Error('Aggiungi almeno una foto dell’attrezzatura.');const fields=Object.fromEntries(['title','category','zone','description','accessories','conditions','insurance'].map(k=>[k,data.get(k).trim()]));await saveWithPhotos(draft,null,images=>{const row={...fields,price:Number(data.get('price')),deposit:Number(data.get('deposit')),images};return f.dataset.id?api.updateListing(f.dataset.id,row):api.publish(row);});close(true);await reload();go('profile');toast(f.dataset.id?'Annuncio aggiornato.':isDemo?'Annuncio aggiunto alla demo.':'Annuncio pubblicato.');}
 if(f.id==='transition-form'){await saveWithPhotos(state.photoDraft,f.dataset.id,photos=>api.transition(f.dataset.id,f.dataset.status,data.get('note').trim(),photos));close(true);await bookingsPage();toast('Stato del noleggio aggiornato.');}
 if(f.id==='block-form'){await api.block(f.dataset.id,data.get('start'),data.get('end'));close(true);await reload();await profilePage();toast('Periodo bloccato.');}
 if(f.id==='message-form'){await api.send(f.dataset.id,data.get('body'));f.reset();await loadMessages();}
}catch(ex){if(err)err.textContent=ex.message;else error(ex);}finally{f.dataset.submitting='false';if(button)button.disabled=false;}});
window.addEventListener('hashchange',()=>{close();route();window.scrollTo(0,0);});
setInterval(()=>{if(state.route==='messages'&&api.user()&&!document.hidden)loadMessages().catch(()=>{});},15000);
setInterval(()=>{if(api.user()&&!document.hidden)refreshCounts().catch(()=>{});},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&api.user())refreshCounts().catch(()=>{});});
navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='NOTIFICATIONS_CHANGED'){refreshCounts().catch(()=>{});if(state.route==='messages')loadMessages().catch(()=>{});}});
try{push.init().catch(()=>{});const recovery=await api.init();await push.refreshBinding().catch(()=>{});await reload();await route();if(recovery)open('<h2>Scegli una nuova password</h2><form id="password-form" class="stack"><label>Nuova password<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="btn primary">Aggiorna password</button><p class="form-error" role="alert"></p></form>');}catch(e){shell(empty('Il set è in preparazione.',esc(e.message),'refresh','Riprova'));}
